mapper.update:
UPDATE crm_whatsapp_conversation
SET contact_id = #{contactId}, update_time = now()
WHERE tenant_id = #{tenantId} AND wa_id = #{waId}

UPDATE crm_whatsapp_conversation
SET lead_id = #{leadId}, update_time = now()
WHERE id = #{id} AND tenant_id = #{tenantId}

UPDATE crm_whatsapp_conversation SET last_message_at = #{lastMessageAt}, last_message_preview = #{lastMessagePreview},
last_outbound_at = #{lastOutboundAt},
update_time = now() WHERE id = #{id}

UPDATE crm_whatsapp_conversation
SET unread_count = 0, update_time = now()
WHERE id = #{id} AND tenant_id = #{tenantId}

UPDATE crm_whatsapp_conversation
SET status = #{status}, update_time = now()
WHERE id = #{id} AND tenant_id = #{tenantId}

mapper.select:
SELECT COUNT(DISTINCT c.id)
FROM crm_whatsapp_conversation c
WHERE c.tenant_id = #{tenantId}

    AND c.phone_number_id = #{phoneNumberId}


    AND (
        (
            c.last_message_at IS NOT NULL

                AND EXTRACT(EPOCH FROM c.last_message_at) * 1000 >= #{startTime}


                AND EXTRACT(EPOCH FROM c.last_message_at) * 1000 <= #{endTime}

        )
        OR (
            c.create_time IS NOT NULL

                AND EXTRACT(EPOCH FROM c.create_time) * 1000 >= #{startTime}


                AND EXTRACT(EPOCH FROM c.create_time) * 1000 <= #{endTime}

        )
        OR EXISTS (
            SELECT 1 FROM crm_whatsapp_message m
            WHERE m.conversation_id = c.id
              AND m.tenant_id = c.tenant_id
              AND m.send_time >= #{startTime}
              AND m.send_time <= #{endTime}
        )
    )
